                ["Keine ABC/XYZ-Daten im gewaehlten Zeitraum."] = "No hay datos ABC/XYZ en el periodo seleccionado.",
                ["Klasse"] = "Clase",
                ["Empfohlener Pruefauftrag"] = "Revision recomendada",
