            ["hi"] = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
            {
                ["Bestellwert im Zeitraum"] = "अवधि में ऑर्डर मूल्य",
                ["Lieferant aufklappen zeigt den Spend nach Warengruppe, Warengruppe aufklappen die einzelnen Materialnummern. Seit dem 27.08.2026 wird nichts mehr abgeschnitten: alle Lieferanten, Warengruppen und Materialien stehen hier. Ein Materialeintrag MIT Bindestrich ist ein echter Artikel, OHNE Bindestrich eine Textbestellung ohne Artikelstamm."] = "आपूर्तिकर्ता खोलने पर सामग्री समूह के अनुसार व्यय दिखता है; सामग्री समूह खोलने पर अलग-अलग सामग्री संख्याएँ दिखती हैं। 27.08.2026 से कुछ भी नहीं काटा जाता: सभी आपूर्तिकर्ता, सामग्री समूह और सामग्रियाँ यहाँ हैं। हाइफ़न वाली सामग्री प्रविष्टि वास्तविक वस्तु है, बिना हाइफ़न वाली बिना मास्टर रिकॉर्ड का टेक्स्ट ऑर्डर है।",
                ["Purchasing volume in CHF by supplier and year. It counts the order item value on the order date, so ordered volume and not goods receipt or invoice. Foreign currencies use the rate from the order document. Complete since 27.08.2026, no longer truncated to the largest suppliers."] = "आपूर्तिकर्ता और वर्ष के अनुसार CHF में क्रय मात्रा। ऑर्डर तिथि पर ऑर्डर मद मूल्य गिना जाता है, यानी ऑर्डर किया गया आयतन, न कि माल प्राप्ति या चालान। विदेशी मुद्राएँ ऑर्डर दस्तावेज़ की दर से बदली जाती हैं। 27.08.2026 से पूर्ण, अब सबसे बड़े आपूर्तिकर्ताओं तक सीमित नहीं।",
                ["What is ordered and not yet here: open quantity per schedule line times unit value. Deliberately period-independent, as of today across all years so old backlogs do not disappear. That is why the amount exceeds a twelve-month view: on 27.08.2026 about two thirds had a delivery date before 2026. Purchase orders only, no quantity contracts."] = "जो ऑर्डर हो चुका है पर अभी आया नहीं: प्रति अनुसूची पंक्ति खुली मात्रा गुणा इकाई मूल्य। जानबूझकर अवधि-निरपेक्ष, आज की स्थिति सभी वर्षों पर, ताकि पुराने बकाया गायब न हों। इसीलिए राशि बारह महीने की दृष्टि से अधिक है: 27.08.2026 को लगभग दो-तिहाई की डिलीवरी तिथि 2026 से पहले थी। केवल ऑर्डर, कोई मात्रा अनुबंध नहीं।",
                ["Bestelltes Volumen am Bestelldatum, nicht Wareneingang und nicht Rechnung. Nur echte Bestellungen, umgerechnet mit dem Kurs vom Bestellbeleg."] = "ऑर्डर तिथि पर ऑर्डर किया गया आयतन, माल प्राप्ति या चालान नहीं। केवल वास्तविक ऑर्डर, ऑर्डर दस्तावेज़ की दर से परिवर्तित।",
                ["Anzahl Bestellbelege im Zeitraum, gezaehlt am Bestelldatum. Ein Beleg mit zwanzig Positionen zaehlt einmal."] = "अवधि में ऑर्डर दस्तावेज़ों की संख्या, ऑर्डर तिथि पर गिनी गई। बीस मदों वाला एक दस्तावेज़ एक बार गिना जाता है।",
                ["Bestellt und noch nicht eingetroffen: offene Menge mal Stueckwert, Stand heute ueber alle Jahre. Enthaelt auch alte, nie geschlossene Einteilungen; nur Bestellungen, keine Mengenkontrakte."] = "ऑर्डर हुआ और अभी नहीं आया: खुली मात्रा गुणा इकाई मूल्य, आज की स्थिति सभी वर्षों पर। इसमें कभी बंद न हुई पुरानी अनुसूचियाँ भी हैं; केवल ऑर्डर, कोई मात्रा अनुबंध नहीं।",
                ["Anzahl Lieferanten mit mindestens einer Bestellposition ungleich null im Zeitraum. Sagt nichts ueber Liefertreue oder Qualitaet aus."] = "अवधि में कम से कम एक शून्येतर ऑर्डर मद वाले आपूर्तिकर्ताओं की संख्या। समयबद्धता या गुणवत्ता के बारे में कुछ नहीं कहता।",
                ["Bewerteter Lagerbestand zum letzten Einkauf-Lauf, eine Stichtagsbetrachtung. Ein frei waehlbarer Stichtag ist nicht moeglich, die Quelle fuehrt nur den Jetzt-Wert."] = "अंतिम क्रय संचालन के समय मूल्यांकित स्टॉक, एक नियत तिथि दृश्य। स्वतंत्र रूप से चुनी तिथि संभव नहीं, स्रोत केवल वर्तमान मूल्य रखता है।",
