                ["Stammdaten nachpflegen; ohne beide Klassen ist keine belastbare Beschaffungsstrategie ableitbar."] = "मास्टर डेटा पूरा करें; दोनों वर्गों के बिना विश्वसनीय खरीद रणनीति नहीं बन सकती।",
                ["Strategisch absichern: Rahmenvertrag, Lieferfaehigkeit und automatische Disposition pruefen."] = "रणनीतिक सुरक्षा: ढांचा अनुबंध, आपूर्ति क्षमता और स्वचालित योजना की समीक्षा करें।",
                ["Versorgungsrisiko priorisieren: Forecast, Sicherheitsbestand und Zweitquelle pruefen."] = "आपूर्ति जोखिम को प्राथमिकता दें: पूर्वानुमान, सुरक्षा स्टॉक और दूसरे स्रोत की समीक्षा करें।",
                ["Standardisieren und Mengen buendeln; Bestellrhythmus und Konditionen optimieren."] = "मानकीकरण और मात्रा एकत्र करें; आदेश आवृत्ति और शर्तों को बेहतर करें।",
                ["Losgroessen, Mindestmengen und schwankende Bedarfsursachen mit dem Disponenten pruefen."] = "योजनाकार के साथ लॉट आकार, न्यूनतम मात्रा और बदलती मांग के कारण जांचें।",
                ["Prozesskosten senken: Katalog, Automatisierung und Sammelbestellungen pruefen."] = "प्रक्रिया लागत घटाएं: कैटलॉग, स्वचालन और समेकित आदेशों की समीक्षा करें।",
                ["Tail Spend reduzieren: buendeln, auslisten oder auf Standardalternativen umstellen."] = "अवशिष्ट खर्च घटाएं: एकत्र करें, हटाएं या मानक विकल्प अपनाएं।",
                ["Klassifikation fachlich pruefen und anschliessend einer Beschaffungsstrategie zuordnen."] = "वर्गीकरण सत्यापित करें और फिर खरीद रणनीति से जोड़ें।",
                ["Lagerwert Einkaufsteile: Verlauf je Woche"] = "क्रय सामग्री का स्टॉक मूल्य: साप्ताहिक रुझान",
                ["Stand Ende Kalenderwoche aus dem taeglichen Einkauf-Lauf, Disponenten"] = "दैनिक क्रय प्रक्रिया से सप्ताह के अंत का मूल्य, योजनाकार",
                ["Gesammelt ab dem 28.09.2026, fruehere Wochen gibt es nicht. Wochen ohne Lauf bleiben leer. Der Wert ist noch nicht gegen MB5L abgeglichen."] = "28.09.2026 से एकत्रित, इससे पहले के सप्ताह नहीं हैं। बिना प्रक्रिया वाले सप्ताह खाली रहते हैं। मूल्य का MB5L से मिलान अभी नहीं हुआ है।",
                ["Wochen"] = "सप्ताह",
                ["Noch kein Verlaufspunkt. Der erste entsteht mit dem naechsten Einkauf-Lauf."] = "अभी कोई बिंदु नहीं है। पहला बिंदु अगली क्रय प्रक्रिया से बनेगा।",
                ["Der Verlauf beginnt. Eine Linie entsteht ab der zweiten Woche."] = "रुझान शुरू हो गया है। रेखा दूसरे सप्ताह से दिखेगी।",
                ["Die Hochachse beginnt nicht bei null, sondern beim tiefsten Wert, damit Veraenderungen sichtbar sind."] = "ऊर्ध्व अक्ष शून्य से नहीं, सबसे कम मूल्य से शुरू होता है, ताकि बदलाव दिखें।",
