            },
            ["sq"] = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
            {
                ["Bestellwert im Zeitraum"] = "Vlera e porositur në periudhë",
                ["Lieferant aufklappen zeigt den Spend nach Warengruppe, Warengruppe aufklappen die einzelnen Materialnummern. Seit dem 27.08.2026 wird nichts mehr abgeschnitten: alle Lieferanten, Warengruppen und Materialien stehen hier. Ein Materialeintrag MIT Bindestrich ist ein echter Artikel, OHNE Bindestrich eine Textbestellung ohne Artikelstamm."] = "Zgjerimi i një furnitori tregon shpenzimin sipas grupit të mallrave; zgjerimi i një grupi mallrash tregon numrat individualë të materialit. Që nga 27.08.2026 asgjë nuk shkurtohet: janë këtu të gjithë furnitorët, grupet e mallrave dhe materialet. Një zë materiali ME vizë është artikull i vërtetë, PA vizë është porosi teksti pa regjistër bazë.",
                ["Purchasing volume in CHF by supplier and year. It counts the order item value on the order date, so ordered volume and not goods receipt or invoice. Foreign currencies use the rate from the order document. Complete since 27.08.2026, no longer truncated to the largest suppliers."] = "Vëllimi i blerjeve në CHF sipas furnitorit dhe vitit. Numërohet vlera e pozicionit të porosisë në datën e porosisë, pra vëllim i porositur dhe jo pranim malli apo faturë. Monedhat e huaja përdorin kursin e dokumentit të porosisë. I plotë që nga 27.08.2026, nuk shkurtohet më te furnitorët më të mëdhenj.",
                ["What is ordered and not yet here: open quantity per schedule line times unit value. Deliberately period-independent, as of today across all years so old backlogs do not disappear. That is why the amount exceeds a twelve-month view: on 27.08.2026 about two thirds had a delivery date before 2026. Purchase orders only, no quantity contracts."] = "Çfarë është porositur dhe ende nuk ka mbërritur: sasia e hapur për rresht orari shumëzuar me vlerën njësi. Qëllimisht i pavarur nga periudha, gjendja e sotme mbi të gjitha vitet, që mbetjet e vjetra të mos zhduken. Prandaj shuma tejkalon një pamje dymbëdhjetëmujore: më 27.08.2026 rreth dy të tretat kishin datë dorëzimi para 2026. Vetëm porosi, pa kontrata sasie.",
                ["Bestelltes Volumen am Bestelldatum, nicht Wareneingang und nicht Rechnung. Nur echte Bestellungen, umgerechnet mit dem Kurs vom Bestellbeleg."] = "Vëllim i porositur në datën e porosisë, jo pranim malli dhe jo faturë. Vetëm porosi të vërteta, konvertuar me kursin e dokumentit të porosisë.",
                ["Anzahl Bestellbelege im Zeitraum, gezaehlt am Bestelldatum. Ein Beleg mit zwanzig Positionen zaehlt einmal."] = "Numri i dokumenteve të porosisë në periudhë, numëruar në datën e porosisë. Një dokument me njëzet pozicione numërohet një herë.",
                ["Bestellt und noch nicht eingetroffen: offene Menge mal Stueckwert, Stand heute ueber alle Jahre. Enthaelt auch alte, nie geschlossene Einteilungen; nur Bestellungen, keine Mengenkontrakte."] = "Porositur dhe ende jo mbërritur: sasia e hapur herë vlera njësi, gjendja e sotme mbi të gjitha vitet. Përfshin edhe orare të vjetra kurrë të mbyllura; vetëm porosi, pa kontrata sasie.",
                ["Anzahl Lieferanten mit mindestens einer Bestellposition ungleich null im Zeitraum. Sagt nichts ueber Liefertreue oder Qualitaet aus."] = "Numri i furnitorëve me të paktën një pozicion porosie jozero në periudhë. Nuk thotë asgjë për përpikëri apo cilësi.",
                ["Bewerteter Lagerbestand zum letzten Einkauf-Lauf, eine Stichtagsbetrachtung. Ein frei waehlbarer Stichtag ist nicht moeglich, die Quelle fuehrt nur den Jetzt-Wert."] = "Vlera e stokut në ekzekutimin e fundit të blerjeve, një pamje në datë fikse. Një datë e zgjedhur lirisht nuk është e mundur, burimi mban vetëm vlerën aktuale.",
                ["Offener Bestellwert (= disponierter Zulauf)"] = "Vlera e porosisë së hapur (= hyrje e planifikuar)",
